style.css:
@-moz-document domain("fanfiction.net") {
/* Root Color Variables */
  :root {
    --color-950: #1F1212;
    --bg-surface: #2C1B1B;
    --bg-comment: #3A2323;
    --bg-tag: #482D2D;
    --border-warm: #5C3A3A;
    --border-accent: #815151;
    --text-main: #E4D3D3; /* Soft creamy text color */
    --text-bright: #F5EFEF;
    --text-muted: #C86565;
    --text-summary: #E0A9A9;
    --link-unvisited: #CC6060;
    --link-visited: #E6BABA;
  }

  /* Global Page Background */
  body, html, #z-body {
    background-color: var(--color-950) !important;
    background-image: url("https://64.media.tumblr.com/940c9dd28d300ef87cee2e97d146875d/40b3901089d4a59c-58/s1280x1920/ff32a8533e2f51cc45a6e5f5c94fd0cb6fedeb6d.png") !important;
    background-repeat: no-repeat !important;
    background-size: cover !important;
    background-position: center center !important;
    background-attachment: fixed !important;
    color: var(--text-main) !important;
  }

  /* Content Areas Set to Darkest Shade (#1F1212) with Soft Cream Text */
  #contentwrapper, #content_parent, #content_wrapper, .print_doc, 
  div.story-list, .gui_table, .z-list, .tborder, .storytextp, .storytext, 
  #storytext, #storytext p, .story-text, .story-text p, #profile_top {
    background-image: none !important;
    background-color: var(--color-950) !important;
    color: var(--text-main) !important;
  }

  /* Tables, Borders & Rows */
  table, tr, td, th, tbody, thead, tfoot, .tcat, .table-bordered, .table {
    background-color: var(--color-950) !important;
    background-image: none !important;
    border-color: var(--border-warm) !important;
    color: var(--text-main) !important;
  }

  /* Horizontal Rules & Dividers */
  hr, .hr, div[style*="border-bottom"], td[style*="border"] {
    border-color: var(--border-warm) !important;
    background-color: var(--border-warm) !important;
  }

  /* Top Navigation, Headers, Toolbars & Footers */
  #top, #z-nav, .z-nav, nav, header, #footer, footer, .footer, 
  .dropdown-menu, .modal, .modal-footer, div.yuimenu, div.yuimenubar, .menulinks, 
  .alt0, .alt1, .alt2, .panel_wrapper, .tabs, .z-toolbar, #fontsize {
    background-color: var(--bg-surface) !important;
    background-image: none !important;
    border-color: var(--border-warm) !important;
    color: var(--text-main) !important;
    box-shadow: none !important;
  }

  /* Story Lists & Rows Hover */
  .z-list:hover, .gui_table tr:hover, .story-list:hover {
    background-color: var(--bg-comment) !important;
    color: var(--text-bright) !important;
  }

  /* Category Header Tags */
  .lc-left, .lc-wrapper, span.lc-left, div.lc-left, #pre_story_links, .pre_story_links {
    background: var(--bg-tag) !important;
    color: var(--text-main) !important;
    border: 1px solid var(--border-warm) !important;
  }

  /* --- Link Color Differentiation --- */
  a:link, .xcontrast_txt, .z-list a.stitle:link, h2 a:link, .story-title:link,
  div.yuimenu a, div.yuimenubar a, .menulinks a {
    color: var(--link-unvisited) !important;
    border: none !important;
  }

  a:visited, .z-list a.stitle:visited, h2 a:visited, .story-title:visited,
  div.yuimenu a:visited, div.yuimenubar a:visited {
    color: var(--link-visited) !important;
  }

  a:hover, a:visited:hover, .z-list a.stitle:hover {
    color: var(--text-bright) !important;
    background-color: transparent !important;
  }

  /* Muted Text & Metadata */
  .z-indent, .gray, span.small, div.sub, .xgray, .footnote, .datetime {
    color: var(--text-muted) !important;
  }

  /* Form Inputs, Buttons, and Select Menus */
  select, input, textarea, button, .btn, .btn-primary {
    background: var(--bg-surface) !important;
    color: var(--text-main) !important;
    border: 1px solid var(--border-accent) !important;
  }

  select:hover, select:focus, input:hover, input:focus, textarea:hover, textarea:focus {
    background: var(--bg-comment) !important;
    border-color: var(--text-bright) !important;
    color: var(--text-bright) !important;
  }

  /* --- Special Symbols & Decorative Accents --- */
  #top a.brand::before, #top .cps-top-brand::before {
    content: "-\2606  " !important;
    display: inline !important;
  }
  
  #top a.brand::after, #top .cps-top-brand::after {
    content: " \2606 -" !important;
    display: inline !important;
  }

  .filter-options label::before, .xgray b::before {
    content: "\26e7  " !important;
    display: inline-block !important;
    color: var(--text-muted) !important;
  }

  /* Clean up clutter */
  .cimage, .a2a_dd, .twitter-timeline, .a2a_kit {
    display: none !important;
  }
}
